import{_ as l,o as i,c as r,a2 as t,j as s,a,t as o}from"./chunks/framework.mRCPFc5l.js";const k=JSON.parse('{"title":"04 · 上下文工程：组装、压缩、溢出、技能","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/context.md","filePath":"deep-dive/context.md","lastUpdated":null}'),p={name:"deep-dive/context.md"},d={tabindex:"0"};function c(n,e,u,h,m,b){return i(),r("div",null,[e[13]||(e[13]=t(`<h1 id="_04-·-上下文工程-组装、压缩、溢出、技能" tabindex="-1">04 · 上下文工程：组装、压缩、溢出、技能 <a class="header-anchor" href="#_04-·-上下文工程-组装、压缩、溢出、技能" aria-label="Permalink to &quot;04 · 上下文工程：组装、压缩、溢出、技能&quot;">​</a></h1><blockquote><p>DSH 的上下文工程可以概括为一句话：<strong>一条日志、两层视图、一个请求</strong>。日志是唯一真源，surface 是模型可见视图，请求由两者重建。本章拆解 system prompt 组装、compaction（压缩）、spill（溢出）、token 计量与技能系统。</p></blockquote><h2 id="_1-心智模型-一条日志、两层视图、一个请求" tabindex="-1">1. 心智模型：一条日志、两层视图、一个请求 <a class="header-anchor" href="#_1-心智模型-一条日志、两层视图、一个请求" aria-label="Permalink to &quot;1. 心智模型：一条日志、两层视图、一个请求&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ ① append-only 会话日志                                     │</span></span>
<span class="line"><span>│   turn/start、user/message、assistant/chunk/message、     │</span></span>
<span class="line"><span>│   tool/result、request/header、compaction/start…end …      │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ② surface（模型可见表层，派生视图）                          │</span></span>
<span class="line"><span>│   只保留三种&quot;产消息&quot;事件：user/message、assistant/message、 │</span></span>
<span class="line"><span>│   tool/result，按 surfaceOp 折叠；replace 遮蔽旧节点        │</span></span>
<span class="line"><span>│   .nodes = 当前可见 seq 列表；.replaceGeneration = 替换次数  │</span></span>
<span class="line"><span>├──────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ ③ 请求（GenerateOptions）                                  │</span></span>
<span class="line"><span>│   system（渲染后提示词）+ tools（schema）+                  │</span></span>
<span class="line"><span>│   messages（deriveMessages() 投影），深冻结后写回日志        │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br></div></div><p>六条链路：<strong>组装</strong>（system prompt）→ <strong>投影</strong>（deriveMessages）→ <strong>压缩</strong>（compact）→ <strong>剪枝</strong>（prune）→ <strong>溢出</strong>（spill）→ <strong>计量</strong>（token meter）。</p><h2 id="_2-system-prompt-组装" tabindex="-1">2. System Prompt 组装 <a class="header-anchor" href="#_2-system-prompt-组装" aria-label="Permalink to &quot;2. System Prompt 组装&quot;">​</a></h2><p><code>ctx.systemPrompt</code> 注册表合并四种贡献（<code>packages/core/system-prompt/src/index.ts:467</code>）：</p>`,7)),s("table",d,[e[6]||(e[6]=s("thead",null,[s("tr",null,[s("th",null,"类型"),s("th",null,"语义"),s("th",null,"排序约定")])],-1)),s("tbody",null,[e[3]||(e[3]=s("tr",null,[s("td",null,[s("strong",null,"section")]),s("td",null,"静态/函数式提示词段落"),s("td",null,[s("code",null,"order"),a(" 升序：-100 harness 身份、0 persona、100-199 工具指南")])],-1)),e[4]||(e[4]=s("tr",null,[s("td",null,[s("strong",null,"context")]),s("td",null,"动态上下文（sandbox 策略、approval 策略等）"),s("td",null,"渲染为空则不贡献")],-1)),e[5]||(e[5]=s("tr",null,[s("td",null,[s("strong",null,"tools")]),s("td",null,"工具 schema 列表"),s("td",null,[s("code",null,"toolOrder"),a(" 配置或字典序")])],-1)),s("tr",null,[e[1]||(e[1]=s("td",null,[s("strong",null,"variable")],-1)),s("td",null,[s("code",null,o(n.name),1),e[0]||(e[0]=a(" 插值变量（provider/model/cwd）",-1))]),e[2]||(e[2]=s("td",null,"全局先填，最近 scope 覆盖",-1))])])]),e[14]||(e[14]=s("p",null,[a("组装流程（9 步）：取 scope 链 → 抑制检查 → 变量解析 → sections/contexts 合并（scoped 同名遮蔽 global）→ 工具 schema 收集（"),s("code",null,"structuredClone"),a(" 脱离）→ order 排序（"),s("code",null,"complete: true"),a(" 的段成为唯一段）→ "),s("code",null,"toolOrder"),a(" 排序 → "),s("strong",null,[s("code",null,"system-prompt/assemble"),a(" waterfall")]),a("（监听器可改写 assembly，返回值权威）→ complete 段恢复。")],-1)),s("p",null,[e[7]||(e[7]=a("渲染细节：严格 ",-1)),s("code",null,o(n.name),1),e[8]||(e[8]=a(" 语法，变量名匹配 ",-1)),e[9]||(e[9]=s("code",null,"^[a-z][a-z0-9_]*$",-1)),e[10]||(e[10]=a("，",-1)),e[11]||(e[11]=s("strong",null,"未知引用直接抛错",-1)),e[12]||(e[12]=a("（fail loud，不静默留空）。",-1))]),e[15]||(e[15]=t(`<div class="tip custom-block"><p class="custom-block-title">面试要点：为什么工具 schema 是&quot;每次请求重新投影&quot;而不是启动时快照？</p><p>因为 scope 化注册表是动态的（restriction、preset 变化、subagent 派生）。<code>wireSchemas(context.scope)</code> 在每次 assembly 时求值当前 scope 可见工具——schema 变化立即反映到下一次请求，无需重启。</p></div><h2 id="_3-运行时上下文快照-runtime-context" tabindex="-1">3. 运行时上下文快照（Runtime Context） <a class="header-anchor" href="#_3-运行时上下文快照-runtime-context" aria-label="Permalink to &quot;3. 运行时上下文快照（Runtime Context）&quot;">​</a></h2><p><code>RuntimeContextProjection.project()</code>（<code>packages/core/agent-loop/src/runtime-context.ts</code>）负责动态上下文（如本会话开头那些 <code>&lt;system-reminder&gt;</code>）：</p><ul><li>与上次保留值比对，<strong>相同则不追加</strong>（不会无限堆叠）</li><li>快照头部固定句：&quot;This snapshot supersedes earlier runtime-context snapshots&quot;</li><li>compaction 遮蔽旧快照时置 null——旧的被新的取代</li></ul><h2 id="_4-压缩-compaction-追加而非删除" tabindex="-1">4. 压缩（Compaction）：追加而非删除 <a class="header-anchor" href="#_4-压缩-compaction-追加而非删除" aria-label="Permalink to &quot;4. 压缩（Compaction）：追加而非删除&quot;">​</a></h2><p>DSH 压缩的核心思想：<strong>日志绝不删除</strong>。压缩只是追加一个带 <code>surfaceOp: {op:&#39;replace&#39;, start, end}</code> 的 <code>user/message</code>（摘要检查点），把一段历史从 surface 遮蔽掉——原文永远在日志里。</p><h3 id="_4-1-两个触发点" tabindex="-1">4.1 两个触发点 <a class="header-anchor" href="#_4-1-两个触发点" aria-label="Permalink to &quot;4.1 两个触发点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>触发</th><th>挂载点</th><th>语义</th></tr></thead><tbody><tr><td><strong>pressure（压力）</strong></td><td><code>agent/pre-step</code>，<strong>在 next() 之前</strong></td><td>计量超过 <code>contextWindow × 0.8</code> 阈值</td></tr><tr><td><strong>context-overflow（溢出）</strong></td><td><code>agent/request-error</code></td><td>provider 确认 <code>CONTEXT_WINDOW_EXCEEDED</code></td></tr></tbody></table><p>为什么挂在这两个点：</p><ul><li>pre-step 时无新消息落地、请求未构建，替换旧表层<strong>不影响本轮</strong>；且每个请求前都有机会检查压力</li><li>溢出只有 provider 报错那一刻才知道，此时需要&quot;恢复有进展&quot;的证明才能重试</li></ul><h3 id="_4-2-压力压缩的决策序列" tabindex="-1">4.2 压力压缩的决策序列 <a class="header-anchor" href="#_4-2-压力压缩的决策序列" aria-label="Permalink to &quot;4.2 压力压缩的决策序列&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. tokenMeter.measure() &lt; threshold？ → 不压缩</span></span>
<span class="line"><span>2. 先剪枝（pruneSession）再重测     ← 模型无关的确定性缩减先行</span></span>
<span class="line"><span>3. 仍超阈值 → selectCompactableRange → compactRegion → 重测</span></span>
<span class="line"><span>4. 最多 compactionRetries + 1 次，仍超 → 抛错</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h3 id="_4-3-范围选择-工具配对平衡" tabindex="-1">4.3 范围选择：工具配对平衡 <a class="header-anchor" href="#_4-3-范围选择-工具配对平衡" aria-label="Permalink to &quot;4.3 范围选择：工具配对平衡&quot;">​</a></h3><p><code>selectCompactableRange</code>（<code>packages/compaction/compaction-basic/src/region.ts:98</code>）：</p><ol><li>从尾向前累计 token，<strong>保留至少 retainTokens 的近期尾部</strong></li><li>向前回退到最近一个<strong>工具配对平衡</strong>的切点——绝不切开 <code>assistant tool-call ↔ tool/result</code> 配对</li></ol><p>配对平衡算法：增量折叠每个切点两侧的未完成 tool-call 数（assistant/message +N、tool/result −1），按 <code>replaceGeneration</code> 缓存。</p><h3 id="_4-4-摘要事务-日志事件即锁" tabindex="-1">4.4 摘要事务：日志事件即锁 <a class="header-anchor" href="#_4-4-摘要事务-日志事件即锁" aria-label="Permalink to &quot;4.4 摘要事务：日志事件即锁&quot;">​</a></h3><p>单次压缩的完整事务（<code>region.ts:152</code>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>compaction/start   ← 锁！此后其它入口被 busy 拒绝</span></span>
<span class="line"><span>  → 摘要调用（复用会话前缀，KV cache 对齐）</span></span>
<span class="line"><span>  → compaction/summary（含 provider/model/usage/rawOutput）</span></span>
<span class="line"><span>  → user/message（checkpoint，surfaceOp: replace）← 唯一 surface 变更</span></span>
<span class="line"><span>compaction/end</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>三个工程细节：</p><ol><li><strong>崩溃自检</strong>：锁不是内存标志而是日志配对——&quot;有 start 无 end&quot; = 崩溃遗留锁，后续入口抛 <code>busy</code>；<code>session/end-seed</code> 之前的遗留 start 视为旧生命周期残留</li><li><strong>摘要必须更小</strong>：<code>estimateMessage(checkpoint) &lt; shadowedTokenCount</code> 否则抛错——防止&quot;压缩反而变大&quot;</li><li><strong>稳定性检查</strong>：自动压缩要求整个 surface 在摘要期间不变（<code>isDeepStrictEqual</code> 比较 nodes）；手动压缩只要求所选 span 不变</li></ol><h3 id="_4-5-溢出恢复-replacegeneration-作为-进展证明" tabindex="-1">4.5 溢出恢复：replaceGeneration 作为&quot;进展证明&quot; <a class="header-anchor" href="#_4-5-溢出恢复-replacegeneration-作为-进展证明" aria-label="Permalink to &quot;4.5 溢出恢复：replaceGeneration 作为&quot;进展证明&quot;&quot;">​</a></h3><div class="language-ts vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// agent/request-error listener（compaction-basic/src/index.ts:179-223 逻辑）</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> generation</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent.session.surface.replaceGeneration</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">compactIfNeeded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(agent, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;context-overflow&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, signal)  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 溢出模式：跳过阈值、retainTokens=0</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (agent.session.surface.replaceGeneration </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> generation) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">return</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { kind: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;retry&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><strong>即使摘要阶段抛异常，只要剪枝的 replace 落地了（generation 前进），就返回 retry</strong>——剪枝本身是&quot;durable reduction&quot;的充分证据。用日志状态而非内存状态判断恢复进展，这是本系统最漂亮的决策之一。</p><h3 id="_4-6-工具结果剪枝-模型无关的确定性缩减" tabindex="-1">4.6 工具结果剪枝：模型无关的确定性缩减 <a class="header-anchor" href="#_4-6-工具结果剪枝-模型无关的确定性缩减" aria-label="Permalink to &quot;4.6 工具结果剪枝：模型无关的确定性缩减&quot;">​</a></h3><p><code>pruneSession</code>（<code>compaction-tool-result-pruner/src/index.ts:136</code>）：</p><ul><li>超 <code>thresholdChars</code>（默认 8192）的 <code>tool/result</code> 内容 → 保留首 4096 + 尾 1024，中段替换为 <code>[... tool result middle pruned ...]</code></li><li>剪切按 Unicode code point（不劈开 surrogate pair）</li><li>每个替换先追加 <code>compaction/prune</code> <strong>影子价格事件</strong>（声明被遮蔽内容的价格），紧接 replace 事件——纯消费方读到计量事件就减去价格，无需保留每节点状态</li></ul><p><strong>为什么剪枝在摘要之前</strong>：剪枝确定性、无模型调用、&quot;必赢&quot;；摘要可能失败（网络、max-tokens、变小校验）。先落地必赢的缩减，再让模型处理剩余部分。</p><h3 id="_4-7-摘要调用-kv-cache-对齐" tabindex="-1">4.7 摘要调用：KV cache 对齐 <a class="header-anchor" href="#_4-7-摘要调用-kv-cache-对齐" aria-label="Permalink to &quot;4.7 摘要调用：KV cache 对齐&quot;">​</a></h3><p>摘要请求 = <strong>会话自己的 system + tools + 被遮蔽消息 + 压缩指令作为最后一条 user 消息</strong>（<code>summarizer.ts:146</code>）：</p><ul><li>这是上次真实请求的<strong>前缀</strong>，提供方前缀缓存不失效</li><li>指令是最后一条 user 消息而非独立 system prompt——保持&quot;真实请求前缀&quot;性质</li><li><code>purpose: &#39;compaction&#39;</code> 标记辅助调用</li></ul><h2 id="_5-spill-工具输出溢出到文件" tabindex="-1">5. Spill：工具输出溢出到文件 <a class="header-anchor" href="#_5-spill-工具输出溢出到文件" aria-label="Permalink to &quot;5. Spill：工具输出溢出到文件&quot;">​</a></h2><p>与剪枝的分工：<strong>剪枝是日志内</strong>（截断+marker），<strong>spill 是跨请求持久</strong>（全文进文件，模型只见定位符）。</p><p>流程（<code>packages/spill/spill-policy/src/index.ts:130</code>，挂在 <code>tools/post-execute</code>）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 纯文本结果 &amp;&amp; bytes &gt; maxInlineBytes？</span></span>
<span class="line"><span>2. ctx.spillStore.saveText({owner, source, suggestedName, content: 全文})</span></span>
<span class="line"><span>3. 预算预留：先估算 notice 字节数，从 cap 扣除后再分配 head/tail 预览</span></span>
<span class="line"><span>4. 替换 = 预览 + spillNotice（locator + 检索提示：&quot;用 read/grep 读该路径&quot;）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>安全细节：本地后端 <code>mkdtemp(&#39;dsh-spill-&#39;)</code> 0700；<code>open(path, &#39;wx&#39;, 0o600)</code> 排他写防符号链接植入；文件名经单射编码中和 <code>../</code>。</p><p><strong>best-effort 降级</strong>：保存失败/无后端/notice 超 cap → 一律保留原始内联结果，<strong>绝不把成功调用变成 isError</strong>。宁可多占上下文，不可丢信息或破坏调用语义。</p><h2 id="_6-token-计量-启发式-usage-锚点" tabindex="-1">6. Token 计量：启发式 + usage 锚点 <a class="header-anchor" href="#_6-token-计量-启发式-usage-锚点" aria-label="Permalink to &quot;6. Token 计量：启发式 + usage 锚点&quot;">​</a></h2><p>不用真实 tokenizer（成本高、路由变化失效），而是：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>启发式：4 字符/token + 块结构开销 4 + 消息角色开销 4</span></span>
<span class="line"><span>锚点：provider 真实 usage（input+cacheRead+cacheWrite+output）</span></span>
<span class="line"><span>规则：真实 usage ≥ 启发式锚点才采用 usage 基线，否则退回 estimated</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><ul><li>纯日志折叠，O(增量事件) 均摊</li><li>有符号 delta 永远从&quot;足够保守&quot;的基线出发——不会低估</li><li>持久化为三个投影单元：<code>tokenUsage</code> / <code>contextPressure</code> / <code>contextBreakdown</code></li><li>UI 展示的是**&quot;下一次请求预计占用&quot;**（projectedTokens）而非上一次的实际值</li></ul><h2 id="_7-技能系统-上下文里只放摘要" tabindex="-1">7. 技能系统：上下文里只放摘要 <a class="header-anchor" href="#_7-技能系统-上下文里只放摘要" aria-label="Permalink to &quot;7. 技能系统：上下文里只放摘要&quot;">​</a></h2><p>分层注册表（<code>ctx.skills</code>）+ 本地文件发现 + 目录 digest 去重：</p><table tabindex="0"><thead><tr><th>机制</th><th>实现</th></tr></thead><tbody><tr><td>发现</td><td>6 类根目录按 rank 扫描（<code>.dsh/skills</code> 100 → bundled 600），<code>&lt;name&gt;/SKILL.md</code> 或 <code>&lt;name&gt;.md</code></td></tr><tr><td>重名</td><td>scope 链最近层直接胜出；层内按 rank → 注册序</td></tr><tr><td>目录发布</td><td>只发 <code>name + description</code>（截断 500 字符），<strong>绝不发正文</strong></td></tr><tr><td>去重</td><td>按条目 digest（sha256）比对；digest 不变则从当前决策移除旧目录</td></tr><tr><td>正文加载</td><td><code>skill</code> 工具按需加载；<code>/name</code> 用户手势直接注入</td></tr><tr><td>生命周期</td><td><code>fs/observed</code> 事件同步失效；watcher 深度 1 监听</td></tr></tbody></table><p>本会话开头的技能目录（<code>&lt;available_skills&gt;</code>）就是这么来的：目录 message 是 <code>form: &#39;catalog&#39;</code> 的 user/message，结构化条目与模型可见文本并存。</p><div class="tip custom-block"><p class="custom-block-title">面试要点：目录为什么用&quot;条目 digest&quot;而不是文本 digest？</p><p>框架文案变化（比如改措辞）不该触发重发；条目级指纹（name+description 的 JSON sha256）只对内容敏感。digest 不变时把旧目录从当前步骤决策中移除——防止上下文堆叠多份目录。</p></div><h2 id="_8-面试要点汇总" tabindex="-1">8. 面试要点汇总 <a class="header-anchor" href="#_8-面试要点汇总" aria-label="Permalink to &quot;8. 面试要点汇总&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">面试要点 1：surface 的 append 与 replace 各是什么？</p><p>append 进尾部；replace 把一段位置跨度换成新节点并 <code>replaceGeneration+1</code>。压缩/剪枝 = 追加 replace 事件，旧事件仍在日志——&quot;修改&quot;被建模为&quot;追加+遮蔽&quot;。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 2：为什么&quot;影子价格协议&quot;存在？</p><p><code>compaction/prune</code> 事件紧邻 replace 声明被遮蔽内容的价格，纯消费方（UI/投影单元）读到就减去，无需保留每节点价格——把&quot;压缩导致占用下降多少&quot;变成 O(1) 日志读取。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 3：<code>shadowedRange.start &gt; end</code> 可能吗？</p><p>可能。replace 落地的摘要节点 seq 是新的大数，但位置在旧区间。所以 <code>shadowedSeqs</code> 是权威集合，<code>shadowedRange</code> 只是位置跨度——按数值区间读会得出荒谬结论。</p></div><div class="tip custom-block"><p class="custom-block-title">面试要点 4：压缩失败为什么只告警不阻断轮次？</p><p>压缩是策略不是流程（pressure 触发在 pre-step）。策略失败不能让对话中断——fail-loud 留给&quot;摘要比原内容还大&quot;这类配置错误（此时抛错），而 transient 失败（网络）保持 degrade。</p></div><p>下一篇：<a href="/deep-dive/orchestration">05 · 多代理编排</a>——subagent 提供方、受限 JS workflow、后台 jobs、持久 goal 循环。</p>`,52))])}const q=l(p,[["render",c]]);export{k as __pageData,q as default};
